def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = 0
    op_d = 0
    for b in op:
        if b == 'C':
            op_c += 1
        else:
            op_d += 1

    remaining = 100 - n

    # Count our defections after opponent cooperated (exploitation attempts)
    # and opponent defections after we cooperated (being exploited)
    opp_exploits = 0
    our_exploits = 0
    for i in range(1, n):
        if me[i - 1] == 'D' and op[i - 1] == 'C' and op[i] == 'C':
            our_exploits += 1
        if me[i - 1] == 'C' and op[i - 1] == 'C' and op[i] == 'D':
            opp_exploits += 1

    # Consecutive streak tracking
    streak_op_c = 0
    streak_op_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C' and streak_op_d == 0:
            streak_op_c += 1
        elif op[i] == 'D' and streak_op_c == 0:
            streak_op_d += 1
        else:
            break

    last_me = me[-1]
    last_op = op[-1]

    # Detect pure strategies early
    if n >= 6:
        if op_c == 0:
            return 'D'
        if op_d == 0:
            if remaining > 12:
                return 'C'
            return 'D'

    # Opponent is overwhelmingly cooperative: exploit near end, build trust before
    if n >= 12 and op_d * 8 <= n:
        if remaining <= 3:
            return 'D'
        if remaining <= 8 and remaining > 0:
            return 'D'
        # small probing but mostly cooperate to preserve relationship
        if remaining > 20 and last_op == 'D':
            return 'D'
        return 'C'

    # Opponent overwhelmingly defecting: defect right back
    if n >= 6 and op_c * 4 <= n:
        return 'D'

    # Near the endgame, exploit based on opponent's cooperation rate
    if remaining <= 2:
        if op_c * 3 >= n * 2:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'D'
    if remaining <= 5:
        if op_c * 2 >= n:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Punish sustained defection
    if streak_op_d >= 3:
        return 'D'
    if streak_op_d == 2:
        if last_me == 'D':
            return 'D'
        return 'D'
    if streak_op_d == 1:
        # Single defection: retaliate once, then forgive
        if last_me == 'D':
            # we already retaliated, return to cooperation
            return 'C'
        return 'D'

    # Opponent just cooperated
    if streak_op_c >= 1:
        # Detect if we're being exploited (opponent defects often after our C)
        if n >= 10 and opp_exploits * 3 >= n and op_d * 4 >= n:
            if remaining > 3:
                return 'D'
        # Occasionally probe against highly cooperative opponent
        if n > 20 and op_d * 10 <= n and remaining > 15:
            if rng.random() < 0.04:
                return 'D'
        return 'C'

    return 'C'
